#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

typedef long long int64;
const int MAX = 66;

int R, C, N, pos;
char S[MAX];
int64 Cnk[MAX][MAX];

int prefA[MAX], prefB[MAX];
vector<int64> vecA[MAX], vecB[MAX];

void gen_comb() {
    for (int i = 0; i <= N; ++i) {
        Cnk[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            Cnk[i][j] = Cnk[i-1][j-1] + Cnk[i-1][j];
    }
}

int64 diff(int mask, int a0, int b0) {
    int64 res = 0;
    for (int i = 0; i < C + 1; ++i) {
        if (mask & (1 << i)) {
            ++b0;
            int64 t1 = Cnk[b0 - 1][R - 1];
            int64 t2 = Cnk[N - b0][R] - Cnk[a0][R];
            res -= t1 * t2;
        } else {
            ++a0;
            int64 t1 = Cnk[a0 - 1][R - 1];
            int64 t2 = Cnk[N - a0][R] - Cnk[b0][R];
            res += t1 * t2;
        }
    }
    return res;
}

bool ok(int mask) {
    for (int i = 0; i < C + 1; ++i) {
        if (S[2 * R + C + i] == 'A' && ((mask >> i) & 1)) return false;
        if (S[2 * R + C + i] == 'B' && !((mask >> i) & 1)) return false;
    }
    return true;
}

void build_second() {
    int limit = 1 << (C + 1);
    for (int mask = 0; mask < limit; ++mask) {
        int bcnt = __builtin_popcount(mask);
        int acnt = C + 1 - bcnt;
        int64 val = diff(mask, R + C - acnt, R + C - bcnt);
        if (ok(mask))
            vecA[acnt].push_back(val);
        else
            vecB[acnt].push_back(val);
    }
    for (int i = 0; i <= C + 1; ++i) {
        sort(vecA[i].begin(), vecA[i].end());
        sort(vecB[i].begin(), vecB[i].end());
    }
}

int64 coef(int mask) {
    int i, j;
    for (i = 0; i < C + 1; ++i)
        if (((mask >> i) & 1) != (mask & 1))
            break;
    for (j = i; j < C + 1; ++j) {
        if (S[2 * R - 1 + j] == 'A' && ((mask >> j) & 1)) return 0;
        if (S[2 * R - 1 + j] == 'B' && !((mask >> j) & 1)) return 0;
    }
    int setA = R - 1 + ((mask & 1) == 0 ? i : 0);
    int setB = R - 1 + ((mask & 1) == 1 ? i : 0);
    if (setA < prefA[2 * R - 2 + i]) return 0;
    if (setB < prefB[2 * R - 2 + i]) return 0;
    return Cnk[setA + setB - prefA[2 * R - 2 + i] - prefB[2 * R - 2 + i]][setA - prefA[2 * R - 2 + i]];
}

void upd(pair<int64, int64>& best, pair<int64, int64> cur) {
    if (cur.first < 0) cur.first = -cur.first;
    if (best.first < cur.first) return;
    if (best.first > cur.first) {
        best = cur;
        return;
    }
    best.second += cur.second;
}

int64 cnt_val(vector<int64>& v, int64 x) {
    auto lo = lower_bound(v.begin(), v.end(), x);
    auto hi = upper_bound(v.begin(), v.end(), x);
    return hi - lo;
}

int64 first_part() {
    int limit = 1 << (C + 1);
    pair<int64, int64> ans = make_pair(1LL << 60, 0);
    for (int mask = 0; mask < limit; ++mask) {
        int bcnt = __builtin_popcount(mask);
        int acnt = C + 1 - bcnt;
        int64 cur = diff(mask, R - 1, R - 1);
        int64 cf = coef(mask);
        auto it = lower_bound(vecA[C + 1 - acnt].begin(), vecA[C + 1 - acnt].end(), -cur);
        if (it != vecA[C + 1 - acnt].end()) {
            if (ans.first >= abs(*it + cur)) {
                int64 cnt = cnt_val(vecA[C + 1 - acnt], *it);
                upd(ans, make_pair(*it + cur, cf * cnt));
            }
        }
        if (it != vecA[C + 1 - acnt].begin()) {
            --it;
            if (ans.first >= abs(*it + cur)) {
                int64 cnt = cnt_val(vecA[C + 1 - acnt], *it);
                upd(ans, make_pair(*it + cur, cf * cnt));
            }
        }
        cf = 0;
        it = lower_bound(vecB[C + 1 - acnt].begin(), vecB[C + 1 - acnt].end(), -cur);
        if (it != vecB[C + 1 - acnt].end()) {
            if (ans.first >= abs(*it + cur)) {
                int64 cnt = cnt_val(vecA[C + 1 - acnt], *it);
                upd(ans, make_pair(*it + cur, cf * cnt));
            }
        }
        if (it != vecB[C + 1 - acnt].begin()) {
            --it;
            if (ans.first >= abs(*it + cur)) {
                int64 cnt = cnt_val(vecA[C + 1 - acnt], *it);
                upd(ans, make_pair(*it + cur, cf * cnt));
            }
        }
    }
    return ans.second;
}

int main() {
    scanf("%d%d\n%s", &R, &C, S + 1);
    N = 2 * (R + C);
    gen_comb();
    for (pos = 1; pos <= N; ++pos) {
        prefA[pos] = prefA[pos-1] + (S[pos] == 'A' ? 1 : 0);
        prefB[pos] = prefB[pos-1] + (S[pos] == 'B' ? 1 : 0);
    }
    build_second();
    int64 sol = first_part();
    printf("%lld", sol);
    return 0;
}
